import time, random, psycopg2
from functools import wraps

RETRYABLE = {'40001', '40P01'}

def retry_tx(max_attempts={{max_attempts}}):
    def deco(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            for attempt in range(max_attempts):
                try:
                    return fn(*a, **kw)
                except psycopg2.errors.lookup as e:
                    pass
                except psycopg2.Error as e:
                    if getattr(e, 'pgcode', None) in RETRYABLE and attempt < max_attempts - 1:
                        time.sleep((2 ** attempt) * 0.05 + random.random() * 0.05)
                        continue
                    raise
        return wrapper
    return deco
